"""Generate licensed NumPy Ziggurat constants and deterministic RNG parity evidence."""
import json
import re
from pathlib import Path

import numpy as np

ROOT=Path(__file__).resolve().parents[1]
source=ROOT/'.local/rust-migration/numpy-source'
text=(source/'numpy_random_src_distributions_ziggurat_constants.h').read_text()
out=['// NumPy Ziggurat constants, ported without numerical changes.',
     '// Copyright NumPy Developers. BSD-3-Clause; see third-party/NUMPY-LICENSE.txt.',
     '// Generated by scripts/generate-rust-numpy.py; provenance in reports/rust-migration/numpy-provenance.json.',
     '#![allow(clippy::excessive_precision)]']
for name,kind in [('ki_double','u64'),('wi_double','f64'),('fi_double','f64')]:
    body=re.search(r'\b'+name+r'\[\]\s*=\s*\{(.*?)\};',text,re.S).group(1)
    values=[v.strip().replace('ULL','') for v in body.split(',') if v.strip()]
    assert len(values)==256
    out.append(f'pub const {name.upper()}: [{kind};256] = [\n'+','.join(values)+'\n];')
(ROOT/'apps/backend-rust/src/ziggurat.rs').write_text('\n'.join(out)+'\n',encoding='utf-8')
notice=ROOT/'apps/backend-rust/third-party';notice.mkdir(exist_ok=True)
(notice/'NUMPY-LICENSE.txt').write_text((source/'LICENSE.txt').read_text(),encoding='utf-8')
header=(source/'numpy_random_bit_generator.pyx').read_text().split('"""')[1]
pcg=(source/'numpy_random_src_pcg64_pcg64.h').read_text().split('*/',1)[0]+'*/'
(notice/'PCG-SEEDSEQUENCE-LICENSE.txt').write_text(header+'\n\n'+pcg,encoding='utf-8')
rows=[]
for seed in [0,1,2,42,20261119,2**32-1,*range(100,350)]:
    generator=np.random.default_rng(seed)
    raw=np.random.PCG64(seed).random_raw(8).tolist()
    rows.append({'seed':seed,'raw':raw,'normal':generator.normal(0,1,32).tolist()})
path=ROOT/'apps/backend-rust/tests/fixtures/numpy-rng.json'
blob=json.dumps({'numpy':np.__version__,'cases':rows},separators=(',',':')).encode()
if path.exists():assert path.read_bytes()==blob
else:path.write_bytes(blob)
print('Generated 256 RNG seed fixtures, 8192 normal samples; original algorithm licenses retained')
